        req: RequestId(6),
        accept: "video/mp4,video/quicktime".into(),
        frame_action: "importVideoFramePayload".into(),
        done_action: "importVideoDone".into(),
        fallback_action: "importVideoBytesPayload".into(),
        sample_stride: 5,
        max_frames: 200,
