            frame_action: "f".into(),
            done_action: "d".into(),
            fallback_action: "b".into(),
            sample_stride: 0,
            max_frames: 0,
            max_long_edge_px: 0,
            fps_hint: 0.0,
            payload: None,
            args: None,
        }
    );
    // `payload`-carrying variant (drop-zone bytes already in memory, no picker needed).
    let with_payload = Effect::RequestMediaFrames {
        req: RequestId(8),
        accept: "video/*".into(),
        frame_action: "f".into(),
        done_action: "d".into(),
        fallback_action: "b".into(),
